"""Functions for validating Rasa projects."""

import functools
import sys
import threading
from contextlib import contextmanager
from pathlib import Path
from typing import Any, Callable, Dict, Generator, List, Optional, ParamSpec, TypeVar

import structlog

from rasa.builder import config
from rasa.builder.exceptions import ValidationError
from rasa.builder.logging_utils import capture_validation_logs
from rasa.cli.validation.bot_config import validate_files
from rasa.core.available_agents import DEFAULT_AGENTS_CONFIG_FOLDER
from rasa.mantle.tools.inventory import ToolInventory, inspect_project_tools
from rasa.mantle.validation import collect_project_findings
from rasa.mantle.validation_finding import ValidationFinding
from rasa.shared.importers.importer import TrainingDataImporter

structlogger = structlog.get_logger()

_P = ParamSpec("_P")
_R = TypeVar("_R")

# Validation touches process-wide state: the `sys.exit` patch, the
# `Configuration` singleton, and Mantle validation importing an agent's `lib`
# and `hooks` packages into `sys.modules` under those bare names. The builder's
# event loop and the MCP server thread both validate, for different agents, so
# every validation runs under this one lock.
_VALIDATION_LOCK = threading.Lock()


def _serialized(validate: Callable[_P, _R]) -> Callable[_P, _R]:
    """Run `validate` while holding the process-wide validation lock.

    The lock is held for the whole validation, so a caller on the event loop
    would block it while waiting. Such callers run validation in a worker
    thread (`asyncio.to_thread`).
    """

    @functools.wraps(validate)
    def locked(*args: _P.args, **kwargs: _P.kwargs) -> _R:
        with _VALIDATION_LOCK:
            return validate(*args, **kwargs)

    return locked


@contextmanager
def _mock_sys_exit() -> Generator[Dict[str, bool], Any, None]:
    """Context manager to prevent sys.exit from being called during validation."""
    was_sys_exit_called = {"value": False}

    def sys_exit_mock(code: int = 0) -> None:
        was_sys_exit_called["value"] = True

    original_exit = sys.exit
    sys.exit = sys_exit_mock  # type: ignore

    try:
        yield was_sys_exit_called
    finally:
        sys.exit = original_exit


def project_sub_agents_path(project_folder: Path) -> Optional[Path]:
    """Return the sub-agents folder of a project, or `None` if it has none.

    Rasa treats an explicitly given sub-agents folder that does not exist as a
    configuration error, while `None` means "use the default folder, if any".
    That default is relative to the working directory, which is not a project
    folder in the builder, so it only resolves to a folder by accident.

    Args:
        project_folder: Root folder of the project.

    Returns:
        The project's sub-agents folder if it exists, otherwise `None`.
    """
    sub_agents_path = project_folder / DEFAULT_AGENTS_CONFIG_FOLDER
    return sub_agents_path if sub_agents_path.is_dir() else None


@_serialized
def validate_project(
    importer: TrainingDataImporter,
    endpoints_path: Path,
    sub_agents_path: Optional[Path],
) -> None:
    """Validate a Rasa project.

    Runs under the process-wide validation lock, so concurrent validations of
    different projects are serialized.

    Args:
        importer: Training data importer with domain, flows, and config.
        endpoints_path: Path to project endpoints config. Validation reads
            endpoints from this file so endpoint-dependent checks (for example
            response rephrasing) run against the same runtime configuration
            used for training.
        sub_agents_path: The project's sub-agents folder, see
            `project_sub_agents_path`.

    Raises:
        ValidationError: If validation fails.
    """
    with capture_validation_logs() as captured_logs:
        try:
            with _mock_sys_exit() as exit_tracker:
                from rasa.core.config.configuration import Configuration

                # Always initialize endpoints explicitly for this validation run.
                # `initialise_empty()` does not reset an existing singleton.
                Configuration.initialise_endpoints(endpoints_path=endpoints_path)
                Configuration.initialise_sub_agents(sub_agents_path=sub_agents_path)

                validate_files(
                    fail_on_warnings=config.VALIDATION_FAIL_ON_WARNINGS,
                    max_history=config.VALIDATION_MAX_HISTORY,
                    importer=importer,
                    sub_agents=str(sub_agents_path) if sub_agents_path else None,
                )

                if exit_tracker["value"]:
                    error_logs = [
                        log for log in captured_logs if log.get("log_level") != "debug"
                    ]
                    structlogger.error(
                        "validation.failed.sys_exit",
                        error_logs=error_logs,
                    )
                    raise ValidationError(
                        "Validation failed with sys.exit", validation_logs=error_logs
                    )

                structlogger.info("validation.success")

        except ValidationError:
            raise

        except BaseException as e:
            if isinstance(e, KeyboardInterrupt):
                raise
            if isinstance(e, SystemExit):
                error_logs = [
                    log for log in captured_logs if log.get("log_level") != "debug"
                ]
                structlogger.error(
                    "validation.failed.sys_exit",
                    error_logs=error_logs,
                )
                raise ValidationError(
                    f"SystemExit during validation: {e}", validation_logs=error_logs
                )
            if isinstance(e, Exception):
                error_msg = f"Validation failed with exception: {e}"
                error_logs = [
                    log for log in captured_logs if log.get("log_level") != "debug"
                ]
                structlogger.error(
                    "validation.failed.exception",
                    error=str(e),
                    validation_logs=error_logs,
                )
                raise ValidationError(error_msg, validation_logs=error_logs)
            raise


def _finding_to_validation_log(finding: ValidationFinding) -> Dict[str, Any]:
    """Shape a Mantle finding as a ``validation_logs`` entry.

    The human-readable ``message`` is placed under the ``event`` key (the key
    consumers such as the copilot MCP validation tool surface as the
    LLM-visible message), while ``code`` and ``docs_url`` are carried as extra
    keys that flow into the ``details`` mapping there.

    Args:
        finding: The finding to convert.

    Returns:
        A dict shaped like the log entries produced by `capture_validation_logs`
        for the v1 validation path.
    """
    return {
        "log_level": finding.severity,
        "event": finding.message,
        "code": finding.code,
        "docs_url": finding.docs_url,
    }


@_serialized
def validate_mantle_project(project_root: Path) -> None:
    """Validate a Mantle (CALM v2) project before packaging.

    Runs under the process-wide validation lock, so concurrent validations of
    different projects are serialized.

    Runs every authoring check via
    `rasa.mantle.validation.collect_project_findings`, which returns every
    finding instead of raising. Warnings are logged but never block
    packaging, mirroring Mantle's own `validate_project` semantics. Errors
    are logged and raised as a single `ValidationError`.

    Args:
        project_root: Directory containing the project's `agent.yml`,
            `integrations.yml`, and `skills/` tree.

    Raises:
        ValidationError: If one or more error-severity findings are found, or
            if collecting findings itself raises unexpectedly (e.g. malformed
            YAML).
    """
    try:
        findings = collect_project_findings(project_root)
    except Exception as e:
        error_msg = f"Mantle validation failed with exception: {e}"
        structlogger.error(
            "validation.mantle.failed.exception",
            error=str(e),
        )
        raise ValidationError(error_msg, validation_logs=[])

    errors: List[ValidationFinding] = [
        finding for finding in findings if finding.severity == "error"
    ]
    warnings: List[ValidationFinding] = [
        finding for finding in findings if finding.severity == "warning"
    ]

    for finding in warnings:
        structlogger.warning(
            "validation.mantle.warning",
            code=finding.code,
            event_info=finding.message,
            docs_url=finding.docs_url,
        )

    if errors:
        for finding in errors:
            structlogger.error(
                "validation.mantle.error",
                code=finding.code,
                event_info=finding.message,
                docs_url=finding.docs_url,
            )
        validation_logs = [_finding_to_validation_log(finding) for finding in errors]
        raise ValidationError(
            f"Mantle project validation found {len(errors)} error(s)",
            validation_logs=validation_logs,
        )

    structlogger.info("validation.success")


@_serialized
def inspect_tools(project_root: Path) -> ToolInventory:
    """Import the project's tool modules and report its tools and broken files.

    Importing tool modules puts the project root on `sys.path` and caches the
    agent's `lib` package in `sys.modules`, the same process-wide state Mantle
    validation touches, so it runs under the validation lock. Callers on the
    event loop run it in a worker thread (`asyncio.to_thread`).

    Args:
        project_root: Directory containing the project's `skills/` tree.

    Returns:
        The project's `@tool` functions and the tool files that fail to load.
    """
    return inspect_project_tools(project_root)
